let mut set = JoinSet::new();
for r in recipients { set.spawn(async move { ask(r).await }); }
let deadline = tokio::time::sleep(budget);
tokio::pin!(deadline);
let mut offers = Vec::new();
while let Some(res) = tokio::select! {
    _ = &mut deadline => None,             // budget exhausted: drop the set, stragglers aborted
    joined = set.join_next() => joined,
} {
    if let Ok(o) = res { offers.push(o); }
}

